def add_to_import(src, pattern, name):
    m = re.search(pattern, src)
    if not m or name in m.group(1):
        return src, False
    base = m.group(1).rstrip()
    if base.endswith(","):
        base = base[:-1].rstrip()
    return src[:m.start(1)] + base + ", " + name + src[m.end(1):], True


